code2='''from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    outside = set()
    q = deque()
    for r in range(h):
        for c in range(w):
            if (r == 0 or r == h - 1 or c == 0 or c == w - 1) and grid[r][c] == 0:
                outside.add((r, c)); q.append((r, c))
    while q:
        r, c = q.popleft()
        for nr, nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0 and (nr,nc) not in outside:
                outside.add((nr,nc)); q.append((nr,nc))
    # Each enclosed component is a rectangular cavity; its fill color is 24 // cavity width.
    components=[]; unseen={(r,c) for r in range(h) for c in range(w) if grid[r][c]==0 and (r,c) not in outside}
    while unseen:
        start=unseen.pop(); comp={start}; stack=[start]
        while stack:
            r,c=stack.pop()
            for nr,nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if (nr,nc) in unseen: unseen.remove((nr,nc)); comp.add((nr,nc)); stack.append((nr,nc))
        width=max(c for r,c in comp)-min(c for r,c in comp)+1
        color=24//width
        components.append((comp,color))
    out=[row[:] for row in grid]
    for comp,color in components:
        for r,c in comp: out[r][c]=color
    return out
